PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?item ?value
WHERE {
  ?item a dbo:Software ;
        dbo:operatingSystem ?os1 ;
        dbo:operatingSystem ?os2 .
  FILTER (?os1 = dbr:Linux && ?os2 = dbr:MacOS)
}
ORDER BY DESC(?value)
LIMIT 10

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?item ?value
WHERE {
  ?item a dbo:University ;
        dbo:location ?location ;
        dbo:affiliation ?affiliation .
  FILTER (?location = dbr:Metro_Manila)
}
ORDER BY DESC(?value)
LIMIT 10

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?item ?value
