PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?item ?value
WHERE {
  ?athlete a dbo:Person ;
            dbo:trainedBy ?ringOfHonor .
  ?ringOfHonor a dbo:WrestlingPromotion ;
                dbo:founder ?founder ;
                dbo:location ?location .
  ?founder a dbo:Person ;
              dbp:birthPlace ?item .
  ?athlete dbo:birthPlace ?value .
}
ORDER BY DESC(?value)
LIMIT 1

PREFIX dbo: <http://dbpedia.org/ontology/>
