PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?other
WHERE {
  ?item a dbo:PresidentialMedalOfFreedomRecipient ;
        dbo:received ?honors ;
        dbo:recipient ?person .
  ?honors dbo:awardedTo ?person ;
         dbo:relatedItem ?other .
}
ORDER BY DESC(?other)
LIMIT 10

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?honoree ?otherHonors
WHERE {
  ?medal a dbo:Award ;
         dbo:recipient ?person .
  ?person dbo:award ?medal ;
          dbo:honoree ?honoree ;
          dbo:otherHonors ?otherHonors .
}
ORDER BY DESC(?otherHonors)
LIMIT 10

