PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?item1 ?value1 ?item2 ?value2
WHERE {
  ?item1 a dbo:City ; 
        dbp:population ?value1 ;
        foaf:topic dbr:Tokyo .
  ?item2 a dbo:City ; 
        dbp:population ?value2 ;
        foaf:topic dbr:Delhi .
}
ORDER BY DESC(?value1 - ?value2)
LIMIT 1

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?tokio ?delhi
WHERE {
  ?tokio a dbo:City ; 
         dbp:population ?tokio .
  ?delhi a dbo:City ; 
         dbp:population ?delhi .
  FILTER (?delhi = dbr:Delhi && ?tokio = dbr:Tokio)
}
ORDER BY DESC(?tokio - ?delhi)
LIMIT 1

